+        let err = SetToolBody::attach_piece(&world, MILL, &testdata("Milling-test.step"), PiecePlace::Spindle { axis: [0.0, 0.0, 1.0], offset: 60.0 }).expect_err("coarse");
+        assert!(err.to_string().contains("too detailed"), "{err}");
+    });
+}
